from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        pairs_at = [[] for _ in range(n + 1)]

        for i, (a, b) in enumerate(conflictingPairs):
            u, v = (a, b) if a < b else (b, a)
            pairs_at[v].append((u, i))

        best = (0, -1)
        second_best = (0, -1)

        base = 0
        benefit = [0] * m

        for right in range(1, n + 1):
            for left, pair_id in pairs_at[right]:
                if left > best[0]:
                    second_best = best
                    best = (left, pair_id)
                elif left >= second_best[0]:
                    second_best = (left, pair_id)

            base += right - best[0]

            if best[1] != -1:
                benefit[best[1]] += best[0] - second_best[0]

        return base + max(benefit)
